-- Tracklet Deterministic Seed Data
-- 1. Canonical Stops (9 stops)
ON CONFLICT (id) DO UPDATE SET
  code = EXCLUDED.code,
  name = EXCLUDED.name,
  latitude = EXCLUDED.latitude,
  longitude = EXCLUDED.longitude,
  nearest_node_id = EXCLUDED.nearest_node_id,
  is_active = EXCLUDED.is_active;

-- 2. Canonical Routes (4 loop routes)
ON CONFLICT (id) DO UPDATE SET
  route_code = EXCLUDED.route_code,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  direction = EXCLUDED.direction,
  path_source = EXCLUDED.path_source,
  path_verified = EXCLUDED.path_verified,
  is_active = EXCLUDED.is_active;

-- 3. Canonical Buses (6 buses)
ON CONFLICT (id) DO UPDATE SET
  bus_number = EXCLUDED.bus_number,
  display_name = EXCLUDED.display_name,
  is_active = EXCLUDED.is_active;

-- 4. Route Stop Occurrences (30 occurrences across 4 routes)
ON CONFLICT (route_id, sequence) DO UPDATE SET
  stop_id = EXCLUDED.stop_id;

-- 5. Scheduled Bus Departures (100 timings mapped to canonical buses)
ON CONFLICT (timing_id) DO UPDATE SET
  bus_id = EXCLUDED.bus_id,
  departure_time = EXCLUDED.departure_time,
  is_special = EXCLUDED.is_special,
  sort_order = EXCLUDED.sort_order,
  updated_at = EXCLUDED.updated_at;


-- ============================================================================
-- 6. Canonical Departments (21 NITC Departments)
-- ============================================================================

ON CONFLICT (department_id) DO UPDATE SET
  department_name = EXCLUDED.department_name;


-- ============================================================================
-- 7. Campus Buildings (100 Landmarks)
-- ============================================================================

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  category = EXCLUDED.category,
  lat = EXCLUDED.lat,
  lng = EXCLUDED.lng,
  nearest_node_id = EXCLUDED.nearest_node_id,
  snap_dist_m = EXCLUDED.snap_dist_m,
  description = EXCLUDED.description,
  created_at = EXCLUDED.created_at,
  lon = EXCLUDED.lon,
  amenity = EXCLUDED.amenity,
  building_type = EXCLUDED.building_type;


-- ============================================================================
-- 8. Canonical NITC Hostels (16 Hostels & Campus Hubs)
-- ============================================================================

ON CONFLICT (hostel_id) DO UPDATE SET
  hostel_name = EXCLUDED.hostel_name,
  short_code = EXCLUDED.short_code,
  gender = EXCLUDED.gender;
